"use client";
import "./styles/skeuo-experience-tabs.css";

import { SkeuoTabs as Tabs } from "./skeuo-tabs";
export type Experience = { id: string; label: string; role: string; period: string; description: string; technologies: string[] };
export function SkeuoExperienceTabs({ items, value, onValueChange, colorMode = "same" }: { items: Experience[]; value: string; onValueChange: (value: string) => void; colorMode?: "same" | "alternating" }) {
  return <div data-sk-root="" className="sk-experience"><Tabs appearance="keys" colorMode={colorMode} label="Experience" value={value} onValueChange={onValueChange} items={items.map(item => ({ value: item.id, label: item.label, content: <article className="sk-experience-page"><header><h3>{item.role}</h3><span>{item.period}</span></header><p>{item.description}</p><div>{item.technologies.map(technology => <span key={technology}>{technology}</span>)}</div><footer>{item.label}</footer></article> }))} /></div>;
}

"use client";
import "./styles/skeuo-tabs.css";

import { useId } from "react";
import type { ReactNode } from "react";
export type TabItem = { value: string; label: string; content: ReactNode; disabled?: boolean };
export function SkeuoTabs({ items, value, onValueChange, label = "Tabs", appearance = "segmented", colorMode = "same" }: { items: TabItem[]; value: string; onValueChange: (value: string) => void; label?: string; appearance?: "segmented" | "keys"; colorMode?: "same" | "alternating" }) {
  const id = useId();
  const active = items.find(item => item.value === value);
  return <div data-sk-root="" className={`sk-tabs ${appearance === "keys" ? "sk-key-tabs" : ""}`} data-color-mode={colorMode}><div className="sk-segmented" role="tablist" aria-label={label}>{items.map((item, index) => <button type="button" id={`${id}-tab-${index}`} key={item.value} role="tab" aria-selected={value === item.value} aria-controls={`${id}-panel-${index}`} tabIndex={value === item.value ? 0 : -1} disabled={item.disabled} onClick={() => onValueChange(item.value)} onKeyDown={e => {
    if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(e.key)) return;
    e.preventDefault();
    const available = items.map((tab, i) => ({ ...tab, index: i })).filter(tab => !tab.disabled);
    if (!available.length) return;
    const current = available.findIndex(tab => tab.value === value);
    const next = e.key === "Home" ? 0 : e.key === "End" ? available.length - 1 : (current + (e.key === "ArrowRight" ? 1 : available.length - 1)) % available.length;
    onValueChange(available[next].value);
    document.getElementById(`${id}-tab-${available[next].index}`)?.focus();
  }}>{item.label}</button>)}</div>{active && <div role="tabpanel" tabIndex={0} id={`${id}-panel-${items.indexOf(active)}`} aria-labelledby={`${id}-tab-${items.indexOf(active)}`} className="sk-tab-panel">{active.content}</div>}</div>;
}

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root]:focus-visible,[data-sk-root] :focus-visible) {outline:2px solid var(--sk-ring);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

@import "./skeuo-base.css";
.sk-experience .sk-tab-panel{ padding-top: 18px; }
@media(max-width:600px){.sk-experience .sk-segmented{ overflow-x: auto; }
.sk-experience .sk-segmented button{ white-space: nowrap; }}


.sk-experience { color: var(--sk-card-ink); }

.sk-experience-page { padding: 24px; border: 1px solid var(--sk-edge); border-radius: 10px; color: var(--sk-ink); background: linear-gradient(145deg,var(--sk-surface-raised),var(--sk-surface)); box-shadow: inset 0 1px 0 var(--sk-highlight),0 4px 0 var(--sk-base),0 5px 0 var(--sk-edge),0 12px 16px var(--sk-shadow); }.sk-experience-page header { display: flex; align-items: center; justify-content: space-between; gap: 20px; }.sk-experience-page h3 { font-size: 15px; font-weight: 500; margin: 0; }.sk-experience-page header span { font: 9px var(--sk-font-mono),monospace; white-space: nowrap; color: var(--sk-muted); }.sk-experience-page p { font-size: 12px; color: var(--sk-muted); line-height: 1.9; }.sk-experience-page > div { display: flex; flex-wrap: wrap; gap: 8px; }.sk-experience-page > div span { padding: 4px 7px; border: 1px solid var(--sk-edge); border-radius: 4px; font-size: 9px; }.sk-experience-page footer { border-top: 1px solid var(--sk-line); padding-top: 16px; margin-top: 20px; font-size: 10px; color: var(--sk-muted); }
@media(max-width:600px){.sk-experience-page header{flex-direction:column;align-items:flex-start;gap:8px;}}

@import "./skeuo-base.css";
.sk-segmented{ display: flex; background: var(--sk-well); border: 1px solid var(--sk-edge); border-radius: 8px; padding: 4px; box-shadow: inset 0 2px 3px var(--sk-shadow),0 1px 0 var(--sk-highlight); }
.sk-segmented button{ flex: 1; padding: 9px 12px; border: 1px solid transparent; border-radius: 5px; background: transparent; font-size: 10px; color: var(--sk-muted); }
.sk-segmented button[aria-selected="true"]{ color: var(--sk-ink); background: linear-gradient(150deg,var(--sk-surface-raised),var(--sk-surface)); border-color: var(--sk-edge); box-shadow: inset 0 1px 0 var(--sk-highlight),0 2px 2px var(--sk-shadow); }
@media(max-width:600px){.sk-segmented button{ font-size: 11px; padding: 11px; }}
.sk-tabs{ width: 100%; }
.sk-tab-panel{ padding-top: 22px; font-size: 13px; color: var(--sk-muted); line-height: 1.8; }
.sk-tabs .sk-segmented button{ font-size: 12px; }
.sk-segmented button:disabled{ opacity: .4; cursor: not-allowed; }

.sk-key-tabs .sk-segmented{display:flex;gap:10px;padding:10px 10px 14px;border-radius:10px;overflow:visible;background:var(--sk-well);box-shadow:inset 0 4px 7px var(--sk-shadow),inset 1px 1px 3px var(--sk-shadow),0 1px var(--sk-highlight);}
.sk-key-tabs .sk-segmented button{--sk-key-tone-highlight:var(--sk-highlight);--sk-key-tone:var(--sk-surface-raised);--sk-key-tone-base:var(--sk-base);flex:1;min-width:0;white-space:nowrap;padding:14px 8px;border:1px solid var(--sk-key-edge);border-radius:6px;color:var(--sk-ink);background:linear-gradient(145deg,var(--sk-key-tone),var(--sk-surface));box-shadow:inset 0 2px var(--sk-key-tone-highlight),inset 0 -2px var(--sk-key-tone-base),0 4px var(--sk-key-tone-base),0 5px var(--sk-key-edge),0 7px 5px var(--sk-shadow);transform:none;transition:transform .15s,box-shadow .15s;}
.sk-key-tabs[data-color-mode="alternating"] .sk-segmented button:nth-child(even){--sk-key-tone-highlight:color-mix(in srgb,var(--sk-accent-bright) 85%,white);--sk-key-edge:var(--sk-accent-edge);--sk-key-tone:var(--sk-accent-bright);--sk-key-tone-base:var(--sk-accent-base);background:linear-gradient(145deg,var(--sk-accent-bright),var(--sk-accent));color:var(--sk-accent-ink);}
.sk-key-tabs .sk-segmented button[aria-selected="true"],.sk-key-tabs .sk-segmented button:active{transform:translateY(3px);box-shadow:inset 0 3px 5px var(--sk-shadow),inset 0 -1px var(--sk-key-tone-highlight),0 1px var(--sk-key-tone-base),0 2px var(--sk-key-edge);}
.sk-key-tabs .sk-segmented button[aria-selected="true"]{border-color:var(--sk-accent);}
.sk-key-tabs .sk-segmented button:focus-visible{outline:2px solid var(--sk-ring);outline-offset:4px;}
@media(prefers-reduced-motion:reduce){.sk-key-tabs .sk-segmented button{transition:none;}}

/* Exact material defaults, with optional host semantic colors. Public host tokens are never written. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper: var(--card, #faf9f5);--sk-album-ink: var(--card-foreground, #45423b);--sk-album-edge: var(--border, #c4c2ba);--sk-album-base: var(--sk-sem-album-base, #d6d4ca);
  --sk-bg: var(--background, #fff); --sk-ink: var(--foreground, #202020); --sk-muted: var(--muted-foreground, #686863); --sk-line: var(--border, #e7e7e4);
  --sk-surface: var(--card, #f5f5f2); --sk-surface-raised: var(--sk-sem-surface-raised, #fafaf8); --sk-well: var(--muted, #e9e9e5);
  --sk-edge: var(--border, #d1d1cb); --sk-highlight: #fff; --sk-base: var(--sk-sem-base, #d9d9d3); --sk-shadow: #00000017;
  --sk-field-shadow: inset 0 3px 6px var(--sk-shadow),inset 1px 1px 2px var(--sk-shadow),0 1px 0 var(--sk-highlight);
  --sk-accent: var(--primary, #365e50); --sk-accent-bright: var(--sk-sem-accent-bright, #487b68); --sk-accent-base: var(--sk-sem-accent-base, #213c32); --sk-accent-edge: var(--sk-sem-accent-edge, #294b3e); --sk-accent-ink: var(--primary-foreground, #fff);
  --sk-key: var(--secondary, #f9f9f7); --sk-key-edge: var(--border, #c6c7c1); --sk-key-base: var(--sk-sem-key-base, #d0d1ca);
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

}
@media(prefers-color-scheme:dark) { :where(html:not(.light):not(.dark):not([data-theme])) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

} }

:where(:root,.light,.dark,[data-theme="light"],[data-theme="dark"]) {
  --sk-sem-accent-bright: color-mix(in srgb,var(--primary) 84%,white);
  --sk-sem-accent-base: color-mix(in srgb,var(--primary) 65%,black);
  --sk-sem-accent-edge: color-mix(in srgb,var(--primary) 78%,black);
  --sk-sem-base: color-mix(in srgb,var(--card) 85%,black);
  --sk-sem-surface-raised: color-mix(in srgb,var(--card) 96%,white);
  --sk-sem-key-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-sem-album-base: color-mix(in srgb,var(--card) 83%,black);
  --sk-card-ink: var(--card-foreground,var(--sk-ink));
  --sk-sem-secondary-raised: color-mix(in srgb,var(--secondary) 96%,white);
  --sk-sem-secondary-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-secondary: var(--secondary,var(--sk-surface));
  --sk-secondary-ink: var(--secondary-foreground,var(--sk-ink));
  --sk-secondary-raised: var(--sk-sem-secondary-raised,var(--sk-surface-raised));
  --sk-secondary-base: var(--sk-sem-secondary-base,var(--sk-base));
  --sk-input-edge: var(--input,var(--sk-edge));
  --sk-ring: var(--ring,var(--sk-accent));
}
